import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%83%8F%E3%83%BC%E3%83%95%E3%83%88%E3%83%BC%E3%83%B3.html","title":"ハーフトーン","lang":"en-US","frontmatter":{},"git":{"createdTime":1755752775000,"updatedTime":1759318871000,"contributors":[{"name":"Kazuma Arino","username":"","email":"hogeika2@gmail.com","commits":10}]},"readingTime":{"minutes":3.62,"words":1085},"filePathRelative":"ハーフトーン.md"}`),a={name:`ハーフトーン.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="ハーフトーン" tabindex="-1"><a class="header-anchor" href="#ハーフトーン"><span>ハーフトーン</span></a></h1><p><a href="./CG.html">CG</a></p><p><a href="./Stippling.html">Stippling</a>を調べていて、ハーフトーンの方が<a href="./MFG.html">MFG</a>で作れそうだな、と思い、関連ページを作る。</p><p><a href="./MdImgr.html">MdImgr</a>のテンプレート<code>![imgs/Halftone/$1](imgs/Halftone/$1)</code></p><h2 id="リンク集" tabindex="-1"><a class="header-anchor" href="#リンク集"><span>リンク集</span></a></h2><ul><li><a href="https://www.shadertoy.com/view/XslGRM" target="_blank" rel="noopener noreferrer">Halftone</a> shadertoyにあった実装</li><li><a href="https://spencerszabados.github.io/blog/2022/bayer-dithering/" target="_blank" rel="noopener noreferrer">Bayer Dithering - Spencer Szabados</a> Bayer Dither</li><li><a href="https://bartwronski.com/2016/10/30/dithering-part-three-real-world-2d-quantization-dithering/" target="_blank" rel="noopener noreferrer">Dithering part three – real world 2D quantization dithering - Bart Wronski</a> bluenoiseとかinterleaved gradient noiseとか</li></ul><h2 id="mfgでの実装" tabindex="-1"><a class="header-anchor" href="#mfgでの実装"><span>MFGでの実装</span></a></h2><p>MFGで実装してみる。</p><h3 id="単にグレーの濃度を白黒の頻度で表すフィルタを作ってみる" tabindex="-1"><a class="header-anchor" href="#単にグレーの濃度を白黒の頻度で表すフィルタを作ってみる"><span>単にグレーの濃度を白黒の頻度で表すフィルタを作ってみる</span></a></h3><p>Stipplingとは違うが、単に2値トーン化として雑にランダムにサンプルするコードを作ってみるとどうだろう？ ようするに単なるハーフトーンの雑な実装だが。</p><div class="language-mfg line-numbers-mode" data-highlighter="prismjs" data-ext="mfg"><pre><code class="language-mfg"><span class="line"><span class="token keyword">def</span> <span class="token tensor-name class-name">result_u8</span> <span class="token operator">|</span>x<span class="token punctuation">,</span> y<span class="token operator">|</span> <span class="token punctuation">{</span></span>
<span class="line">   <span class="token keyword">let</span> gray <span class="token operator">=</span> grayT<span class="token punctuation">(</span>x<span class="token punctuation">,</span> y<span class="token punctuation">)</span></span>
<span class="line">   <span class="token builtin">ifel</span><span class="token punctuation">(</span>rand<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">&lt;</span> gray<span class="token punctuation">,</span> <span class="token builtin">u8</span><span class="token punctuation">[</span><span class="token number">0xff</span><span class="token punctuation">,</span> <span class="token number">0xff</span><span class="token punctuation">,</span> <span class="token number">0xff</span><span class="token punctuation">,</span> <span class="token number">0xff</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token builtin">u8</span><span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">0xff</span><span class="token punctuation">]</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><img src="/RandomThoughts/assets/2025_0821_122411-CWK4OCUr.png" alt="imgs/Halftone/2025_0821_122411.png"></p><p>けっこういいけど、これ、なんかガンマ補正してない時の暗くなるのと同じ結果に見えるな。 アルファをガンマ補正するのはどうなんだ問題と同じでしないのが正しい気もするけれど、 あえてやってみるとどうなるだろう？</p><div class="language-mfg line-numbers-mode" data-highlighter="prismjs" data-ext="mfg"><pre><code class="language-mfg"><span class="line"><span class="token keyword">def</span> <span class="token tensor-name class-name">result_u8</span> <span class="token operator">|</span>x<span class="token punctuation">,</span> y<span class="token operator">|</span> <span class="token punctuation">{</span></span>
<span class="line">   <span class="token keyword">let</span> lgray <span class="token operator">=</span> grayT<span class="token punctuation">(</span>x<span class="token punctuation">,</span> y<span class="token punctuation">)</span></span>
<span class="line">   <span class="token keyword">let</span> gray <span class="token operator">=</span> linear2gamma<span class="token punctuation">(</span>lgray<span class="token punctuation">)</span></span>
<span class="line">   <span class="token builtin">ifel</span><span class="token punctuation">(</span>rand<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">&lt;</span> gray<span class="token punctuation">,</span> <span class="token builtin">u8</span><span class="token punctuation">[</span><span class="token number">0xff</span><span class="token punctuation">,</span> <span class="token number">0xff</span><span class="token punctuation">,</span> <span class="token number">0xff</span><span class="token punctuation">,</span> <span class="token number">0xff</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token builtin">u8</span><span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">0xff</span><span class="token punctuation">]</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><img src="/RandomThoughts/assets/2025_0821_122722-j-W-Sm6T.png" alt="imgs/Halftone/2025_0821_122722.png"></p><p>やはりこっちの方が正しい気はするな。</p><p>拡大するとランダムさがトーンとして汚いので、やはりbluenoiseの方が良さそうではある。</p><p><img src="/RandomThoughts/assets/2025_0821_122841-DSxbEJPV.png" alt="imgs/Halftone/2025_0821_122841.png"></p><p>ちょっとハーフトーンは面白そうだな。論文を調べてみてあとでページを分けよう。</p><h3 id="shadertoyの実装を移植してみる" tabindex="-1"><a class="header-anchor" href="#shadertoyの実装を移植してみる"><span>shadertoyの実装を移植してみる</span></a></h3><p>shadertoyでハーフトーンで眺めていて見つけた以下を移植してみる。</p><p><a href="https://www.shadertoy.com/view/XslGRM" target="_blank" rel="noopener noreferrer">Halftone</a></p><p>最初は理解せずに書いたが、理解してみるとcosの周期パターンにすぎない事に気づく。sindとかcosdはいらなかったな。</p><div class="language-mfg line-numbers-mode" data-highlighter="prismjs" data-ext="mfg"><pre><code class="language-mfg"><span class="line"><span class="token attribute atrule">@param_f32</span> threshold<span class="token punctuation">(</span>SLIDER<span class="token punctuation">,</span> label<span class="token operator">=</span><span class="token string">&quot;閾値&quot;</span><span class="token punctuation">,</span> init<span class="token operator">=</span><span class="token number">0.6</span><span class="token punctuation">,</span> <span class="token builtin">min</span><span class="token operator">=</span><span class="token number">0.0</span><span class="token punctuation">,</span> <span class="token builtin">max</span><span class="token operator">=</span><span class="token number">1.0</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">let</span> PI <span class="token operator">=</span> <span class="token number">3.1415926</span></span>
<span class="line"><span class="token keyword">let</span> PI180 <span class="token operator">=</span> PI <span class="token operator">/</span> <span class="token number">180.0</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">fn</span> <span class="token function">sind</span> <span class="token operator">|</span>a<span class="token punctuation">:</span><span class="token builtin">f32</span><span class="token operator">|</span> <span class="token punctuation">{</span> sin<span class="token punctuation">(</span>a<span class="token operator">*</span>PI180<span class="token punctuation">)</span> <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">fn</span> <span class="token function">cosd</span> <span class="token operator">|</span>a<span class="token punctuation">:</span> <span class="token builtin">f32</span><span class="token operator">|</span> <span class="token punctuation">{</span> cos<span class="token punctuation">(</span>a<span class="token operator">*</span>PI180<span class="token punctuation">)</span> <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">fn</span> <span class="token function">added</span> <span class="token operator">|</span>sh<span class="token punctuation">:</span> <span class="token builtin">f32v2</span><span class="token punctuation">,</span> sa<span class="token punctuation">:</span><span class="token builtin">f32</span><span class="token punctuation">,</span> ca<span class="token punctuation">:</span><span class="token builtin">f32</span><span class="token punctuation">,</span> c<span class="token punctuation">:</span><span class="token builtin">f32v2</span><span class="token punctuation">,</span> d<span class="token punctuation">:</span><span class="token builtin">f32</span> <span class="token operator">|</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token number">0.5</span> <span class="token operator">+</span> <span class="token number">0.25</span> <span class="token operator">*</span> cos<span class="token punctuation">(</span><span class="token punctuation">(</span>sh<span class="token punctuation">.</span>x <span class="token operator">*</span> sa <span class="token operator">+</span> sh<span class="token punctuation">.</span>y <span class="token operator">*</span> ca <span class="token operator">+</span> c<span class="token punctuation">.</span>x<span class="token punctuation">)</span> <span class="token operator">*</span> d<span class="token punctuation">)</span> <span class="token operator">+</span> <span class="token number">0.25</span> <span class="token operator">*</span> cos<span class="token punctuation">(</span><span class="token punctuation">(</span>sh<span class="token punctuation">.</span>x <span class="token operator">*</span> ca <span class="token operator">-</span> sh<span class="token punctuation">.</span>y <span class="token operator">*</span> sa <span class="token operator">+</span> c<span class="token punctuation">.</span>y<span class="token punctuation">)</span> <span class="token operator">*</span> d<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">def</span> <span class="token tensor-name class-name">result_u8</span> <span class="token operator">|</span>x<span class="token punctuation">,</span> y<span class="token operator">|</span> <span class="token punctuation">{</span></span>
<span class="line">   <span class="token keyword">let</span> dstCoord <span class="token operator">=</span> <span class="token builtin">f32</span><span class="token punctuation">(</span><span class="token punctuation">[</span>x<span class="token punctuation">,</span> y<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token operator">/</span><span class="token builtin">input_u8</span><span class="token punctuation">.</span>extent<span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span></span>
<span class="line">   <span class="token keyword">let</span> rotationCenter <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token number">0.5</span><span class="token punctuation">,</span> <span class="token number">0.5</span><span class="token punctuation">]</span></span>
<span class="line">   <span class="token keyword">let</span> shift <span class="token operator">=</span> dstCoord <span class="token operator">-</span> rotationCenter</span>
<span class="line">   <span class="token keyword">let</span> dotSize <span class="token operator">=</span> <span class="token number">3.0</span></span>
<span class="line">   <span class="token keyword">let</span> angle <span class="token operator">=</span> <span class="token number">45.0</span></span>
<span class="line">   <span class="token keyword">let</span> rasterPattern <span class="token operator">=</span> added<span class="token punctuation">(</span>shift<span class="token punctuation">,</span> sind<span class="token punctuation">(</span>angle<span class="token punctuation">)</span><span class="token punctuation">,</span> cosd<span class="token punctuation">(</span>angle<span class="token punctuation">)</span><span class="token punctuation">,</span> rotationCenter<span class="token punctuation">,</span> PI <span class="token operator">/</span> dotSize <span class="token operator">*</span> <span class="token number">680.0</span><span class="token punctuation">)</span></span>
<span class="line">   <span class="token keyword">let</span> srcPixel <span class="token operator">=</span> <span class="token builtin">input_u8</span><span class="token punctuation">(</span>x<span class="token punctuation">,</span> y<span class="token punctuation">)</span></span>
<span class="line">        </span>
<span class="line">   <span class="token keyword">let</span> avg <span class="token operator">=</span> to_xyza<span class="token punctuation">(</span>srcPixel<span class="token punctuation">)</span><span class="token punctuation">.</span>y</span>
<span class="line">   <span class="token keyword">let</span> gray <span class="token operator">=</span> <span class="token punctuation">(</span>rasterPattern <span class="token operator">*</span> threshold <span class="token operator">+</span> avg <span class="token operator">-</span> threshold<span class="token punctuation">)</span> <span class="token operator">/</span> <span class="token punctuation">(</span><span class="token number">1.0</span> <span class="token operator">-</span> threshold<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment"># check raster pattern</span></span>
<span class="line">    <span class="token comment"># let gray = rasterPattern</span></span>
<span class="line">    <span class="token punctuation">[</span><span class="token operator">*</span><span class="token builtin">vec3</span><span class="token punctuation">(</span>gray<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">1.0</span><span class="token punctuation">]</span> <span class="token operator">|&gt;</span> lbgra_to_u8color<span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>結果は以下。</p><p><img src="/RandomThoughts/assets/2025_0821_125719-Bq6-VI0v.png" alt="imgs/Halftone/2025_0821_125719.png"></p><p>おお、結構いい感じだな。</p><h3 id="bayerディザー" tabindex="-1"><a class="header-anchor" href="#bayerディザー"><span>Bayerディザー</span></a></h3><p>shadertoyのブレンディング式はどこから来ているのかなぁ、と調べていて、以下のブログに行き当たる。</p><p><a href="https://spencerszabados.github.io/blog/2022/bayer-dithering/" target="_blank" rel="noopener noreferrer">Bayer Dithering - Spencer Szabados</a></p><p>ここからどうやって探したのか思い出せないが、以下と同じtxtファイルのinternet archiveを参照しているページがあって、そこからDHALF.txtを読んだ。</p><p><a href="https://gist.github.com/robertlugg/f0b618587c2981b744716999573c5b65" target="_blank" rel="noopener noreferrer">DHALF.TXT</a></p><p>という事でこれを単純に実装してみる。</p><div class="language-mfg line-numbers-mode" data-highlighter="prismjs" data-ext="mfg"><pre><code class="language-mfg"><span class="line"><span class="token comment"># bayer pattern</span></span>
<span class="line"><span class="token keyword">def</span> pattern <span class="token keyword">by</span> </span>
<span class="line"><span class="token punctuation">[</span></span>
<span class="line">    <span class="token punctuation">[</span> <span class="token number">0.0</span><span class="token punctuation">,</span> <span class="token number">32.0</span><span class="token punctuation">,</span>  <span class="token number">8.0</span><span class="token punctuation">,</span> <span class="token number">40.0</span><span class="token punctuation">,</span>  <span class="token number">2.0</span><span class="token punctuation">,</span> <span class="token number">34.0</span><span class="token punctuation">,</span> <span class="token number">10.0</span><span class="token punctuation">,</span> <span class="token number">42.0</span><span class="token punctuation">]</span><span class="token punctuation">,</span> </span>
<span class="line">    <span class="token punctuation">[</span><span class="token number">48.0</span><span class="token punctuation">,</span> <span class="token number">16.0</span><span class="token punctuation">,</span> <span class="token number">56.0</span><span class="token punctuation">,</span> <span class="token number">24.0</span><span class="token punctuation">,</span> <span class="token number">50.0</span><span class="token punctuation">,</span> <span class="token number">18.0</span><span class="token punctuation">,</span> <span class="token number">58.0</span><span class="token punctuation">,</span> <span class="token number">26.0</span><span class="token punctuation">]</span><span class="token punctuation">,</span>  </span>
<span class="line">    <span class="token punctuation">[</span><span class="token number">12.0</span><span class="token punctuation">,</span> <span class="token number">44.0</span><span class="token punctuation">,</span>  <span class="token number">4.0</span><span class="token punctuation">,</span> <span class="token number">36.0</span><span class="token punctuation">,</span> <span class="token number">14.0</span><span class="token punctuation">,</span> <span class="token number">46.0</span><span class="token punctuation">,</span>  <span class="token number">6.0</span><span class="token punctuation">,</span> <span class="token number">38.0</span><span class="token punctuation">]</span><span class="token punctuation">,</span>  </span>
<span class="line">    <span class="token punctuation">[</span><span class="token number">60.0</span><span class="token punctuation">,</span> <span class="token number">28.0</span><span class="token punctuation">,</span> <span class="token number">52.0</span><span class="token punctuation">,</span> <span class="token number">20.0</span><span class="token punctuation">,</span> <span class="token number">62.0</span><span class="token punctuation">,</span> <span class="token number">30.0</span><span class="token punctuation">,</span> <span class="token number">54.0</span><span class="token punctuation">,</span> <span class="token number">22.0</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">[</span> <span class="token number">3.0</span><span class="token punctuation">,</span> <span class="token number">35.0</span><span class="token punctuation">,</span> <span class="token number">11.0</span><span class="token punctuation">,</span> <span class="token number">43.0</span><span class="token punctuation">,</span>  <span class="token number">1.0</span><span class="token punctuation">,</span> <span class="token number">33.0</span><span class="token punctuation">,</span>  <span class="token number">9.0</span><span class="token punctuation">,</span> <span class="token number">41.0</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">[</span><span class="token number">51.0</span><span class="token punctuation">,</span> <span class="token number">19.0</span><span class="token punctuation">,</span> <span class="token number">59.0</span><span class="token punctuation">,</span> <span class="token number">27.0</span><span class="token punctuation">,</span> <span class="token number">49.0</span><span class="token punctuation">,</span> <span class="token number">17.0</span><span class="token punctuation">,</span> <span class="token number">57.0</span><span class="token punctuation">,</span> <span class="token number">25.0</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">[</span><span class="token number">15.0</span><span class="token punctuation">,</span> <span class="token number">47.0</span><span class="token punctuation">,</span>  <span class="token number">7.0</span><span class="token punctuation">,</span> <span class="token number">39.0</span><span class="token punctuation">,</span> <span class="token number">13.0</span><span class="token punctuation">,</span> <span class="token number">45.0</span><span class="token punctuation">,</span>  <span class="token number">5.0</span><span class="token punctuation">,</span> <span class="token number">37.0</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">[</span><span class="token number">63.0</span><span class="token punctuation">,</span> <span class="token number">31.0</span><span class="token punctuation">,</span> <span class="token number">55.0</span><span class="token punctuation">,</span> <span class="token number">23.0</span><span class="token punctuation">,</span> <span class="token number">61.0</span><span class="token punctuation">,</span> <span class="token number">29.0</span><span class="token punctuation">,</span> <span class="token number">53.0</span><span class="token punctuation">,</span> <span class="token number">21.0</span><span class="token punctuation">]</span>  </span>
<span class="line"><span class="token punctuation">]</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">let</span> PATTERN_WIDTH <span class="token operator">=</span> pattern<span class="token punctuation">.</span>extent<span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">let</span> PAT_MAX <span class="token operator">=</span> <span class="token builtin">f32</span><span class="token punctuation">(</span>PATTERN_WIDTH<span class="token operator">^</span><span class="token number">2</span><span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span class="token keyword">def</span> <span class="token tensor-name class-name">result_u8</span> <span class="token operator">|</span>x<span class="token punctuation">,</span> y<span class="token operator">|</span> <span class="token punctuation">{</span></span>
<span class="line">   <span class="token keyword">let</span> pxy <span class="token operator">=</span> <span class="token punctuation">[</span>x<span class="token punctuation">,</span> y<span class="token punctuation">]</span><span class="token operator">%</span>PATTERN_WIDTH</span>
<span class="line">   <span class="token keyword">let</span> pval <span class="token operator">=</span> pattern<span class="token punctuation">(</span><span class="token operator">*</span>pxy<span class="token punctuation">)</span><span class="token operator">/</span>PAT_MAX</span>
<span class="line"></span>
<span class="line">   <span class="token keyword">let</span> level <span class="token operator">=</span> <span class="token builtin">input_u8</span><span class="token punctuation">(</span>x<span class="token punctuation">,</span> y<span class="token punctuation">)</span> <span class="token operator">|&gt;</span> to_xyza<span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">.</span>y</span>
<span class="line">   <span class="token keyword">let</span> gray <span class="token operator">=</span> <span class="token builtin">ifel</span><span class="token punctuation">(</span>level <span class="token operator">&gt;</span> pval<span class="token punctuation">,</span> <span class="token number">1.0</span><span class="token punctuation">,</span> <span class="token number">0.0</span><span class="token punctuation">)</span>   </span>
<span class="line"></span>
<span class="line">    <span class="token punctuation">[</span><span class="token operator">*</span><span class="token builtin">vec3</span><span class="token punctuation">(</span>gray<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">1.0</span><span class="token punctuation">]</span> <span class="token operator">|&gt;</span> lbgra_to_u8color<span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>超簡単。</p><p>適用した結果が以下。単なるグレースケールに見える。</p><p><img src="/RandomThoughts/assets/2025_0823_104152-BCC3YT9t.png" alt="imgs/Halftone/2025_0823_104152.png"></p><p>でもアップにすると白黒2値だという事がわかる。</p><p><img src="/RandomThoughts/assets/2025_0823_104220-MtYPj4G9.png" alt="imgs/Halftone/2025_0823_104220.png"></p><p>あまりにもグレースケールっぽくて面白さはなくなってしまうな。</p><p>カラー版もやってみよう。グローバル変数やパターンは白黒と一緒。</p><div class="language-mfg line-numbers-mode" data-highlighter="prismjs" data-ext="mfg"><pre><code class="language-mfg"><span class="line"><span class="token keyword">def</span> <span class="token tensor-name class-name">result_u8</span> <span class="token operator">|</span>x<span class="token punctuation">,</span> y<span class="token operator">|</span> <span class="token punctuation">{</span></span>
<span class="line">   <span class="token keyword">let</span> pxy <span class="token operator">=</span> <span class="token punctuation">[</span>x<span class="token punctuation">,</span> y<span class="token punctuation">]</span><span class="token operator">%</span>PATTERN_WIDTH</span>
<span class="line">   <span class="token keyword">let</span> pval <span class="token operator">=</span> pattern<span class="token punctuation">(</span><span class="token operator">*</span>pxy<span class="token punctuation">)</span><span class="token operator">/</span>PAT_MAX</span>
<span class="line"></span>
<span class="line">   <span class="token keyword">let</span> lbgra <span class="token operator">=</span> <span class="token builtin">input_u8</span><span class="token punctuation">(</span>x<span class="token punctuation">,</span> y<span class="token punctuation">)</span> <span class="token operator">|&gt;</span> to_lbgra<span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span></span>
<span class="line">   <span class="token keyword">let</span> lbgr_q <span class="token operator">=</span> <span class="token builtin">ifel</span><span class="token punctuation">(</span>lbgra<span class="token punctuation">.</span>xyz <span class="token operator">&gt;</span> pval <span class="token punctuation">,</span> <span class="token builtin">vec3</span><span class="token punctuation">(</span><span class="token number">1.0</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token builtin">vec3</span><span class="token punctuation">(</span><span class="token number">0.0</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token punctuation">[</span><span class="token operator">*</span>lbgr_q<span class="token punctuation">,</span> lbgra<span class="token punctuation">.</span>w<span class="token punctuation">]</span> <span class="token operator">|&gt;</span> lbgra_to_u8color<span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>これも簡単。 結果は以下。</p><p><img src="/RandomThoughts/assets/2025_0823_104949-CrH9Dy5U.png" alt="imgs/Halftone/2025_0823_104949.png"></p><p>なんか暗くなっちゃうな。このBayerパターンはガンマ補正の具合がいまいちなのではないか？</p><p>拡大すると以下。</p><p><img src="/RandomThoughts/assets/2025_0823_105025-BUbw-xNK.png" alt="imgs/Halftone/2025_0823_105025.png"></p><p>昔のパソコンみたい。</p><h3 id="ブルーノイズでサンプリング" tabindex="-1"><a class="header-anchor" href="#ブルーノイズでサンプリング"><span>ブルーノイズでサンプリング</span></a></h3><p>ブルーノイズのテクスチャで単純にサンプリングする、というのも試してみよう。 と軽くPythonのvoid and clusterのコードで作ってみたが、512x512で２時間も掛かった…ちょっと1024x1024は作れないな。</p><p>とりあえず512x512でいいでしょう。 256x256をBGRAに4面パックする感じにしておく。</p><div class="language-mfg line-numbers-mode" data-highlighter="prismjs" data-ext="mfg"><pre><code class="language-mfg"><span class="line"><span class="token keyword">def</span> bluenoise <span class="token keyword">by</span> load<span class="token punctuation">(</span><span class="token string">&quot;bluenoise512_packed.png&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">let</span> T_SIZE<span class="token operator">=</span>bluenoise<span class="token punctuation">.</span>extent<span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">let</span> B_SIZE<span class="token operator">=</span>T_SIZE<span class="token operator">*</span><span class="token number">2</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">def</span> <span class="token tensor-name class-name">result_u8</span> <span class="token operator">|</span>x<span class="token punctuation">,</span> y<span class="token operator">|</span> <span class="token punctuation">{</span></span>
<span class="line">   <span class="token keyword">let</span> txy <span class="token operator">=</span> <span class="token punctuation">[</span>x<span class="token punctuation">,</span> y<span class="token punctuation">]</span><span class="token operator">%</span>B_SIZE</span>
<span class="line">   <span class="token keyword">let</span> pxy <span class="token operator">=</span> txy<span class="token operator">%</span>T_SIZE</span>
<span class="line">   </span>
<span class="line">   <span class="token keyword">let</span> packed <span class="token operator">=</span> bluenoise<span class="token punctuation">(</span><span class="token operator">*</span>pxy<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">   <span class="token keyword">let</span> chxy <span class="token operator">=</span> txy<span class="token operator">/</span>T_SIZE <span class="token comment"># 0または1</span></span>
<span class="line">   <span class="token keyword">let</span> ch <span class="token operator">=</span> chxy<span class="token punctuation">.</span>y<span class="token operator">*</span><span class="token number">2</span><span class="token operator">+</span>chxy<span class="token punctuation">.</span>x <span class="token comment">#0〜3 </span></span>
<span class="line">   </span>
<span class="line">   <span class="token keyword">let</span> gray <span class="token operator">=</span> <span class="token builtin">ifel</span><span class="token punctuation">(</span>ch <span class="token operator">==</span> <span class="token number">0</span><span class="token punctuation">,</span> packed<span class="token punctuation">.</span>x<span class="token punctuation">,</span> <span class="token operator">...</span><span class="token punctuation">)</span></span>
<span class="line">                     <span class="token builtin">elif</span><span class="token punctuation">(</span>ch <span class="token operator">==</span> <span class="token number">1</span><span class="token punctuation">,</span> packed<span class="token punctuation">.</span>y<span class="token punctuation">,</span> <span class="token operator">...</span><span class="token punctuation">)</span></span>
<span class="line">                     <span class="token builtin">elif</span><span class="token punctuation">(</span>ch <span class="token operator">==</span> <span class="token number">2</span><span class="token punctuation">,</span> packed<span class="token punctuation">.</span>z<span class="token punctuation">,</span> packed<span class="token punctuation">.</span>w<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment"># u8[*vec3(gray), 255]</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">let</span> level <span class="token operator">=</span> <span class="token builtin">input_u8</span><span class="token punctuation">(</span>x<span class="token punctuation">,</span> y<span class="token punctuation">)</span> <span class="token operator">|&gt;</span> to_xyza<span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">.</span>y</span>
<span class="line">    <span class="token builtin">ifel</span> <span class="token punctuation">(</span><span class="token builtin">f32</span><span class="token punctuation">(</span>gray<span class="token punctuation">)</span><span class="token operator">/</span><span class="token number">255.0</span> <span class="token operator">&lt;</span> level<span class="token punctuation">,</span></span>
<span class="line">       <span class="token builtin">u8</span><span class="token punctuation">(</span><span class="token builtin">vec4</span><span class="token punctuation">(</span><span class="token number">255</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token builtin">u8</span><span class="token punctuation">[</span><span class="token operator">*</span><span class="token builtin">vec3</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">255</span><span class="token punctuation">]</span></span>
<span class="line">       <span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>まぁこんな感じで。</p><p><img src="/RandomThoughts/assets/2025_0823_230333-BVUNx2IR.png" alt="imgs/Halftone/2025_0823_230333.png"></p><p>割と綺麗ではある。アップにすると512x512の境界が意外と目立ってしまうが。</p><p>写真に使うと良く論文とかにある感じになって良いね。</p><p><img src="/RandomThoughts/assets/2025_0823_230411-CxnxrD4G.png" alt="imgs/Halftone/2025_0823_230411.png"></p><p>なかなか勉強にはなる。</p><h3 id="interleaved-gradient-noiseでサンプリング" tabindex="-1"><a class="header-anchor" href="#interleaved-gradient-noiseでサンプリング"><span>Interleaved gradient noiseでサンプリング</span></a></h3><p>bluenoiseはちょっと手間なので代わりは無いかな、と探していたら、Interleaved gradient noiseというのが勧められていた。</p><p><a href="https://bartwronski.com/2016/10/30/dithering-part-three-real-world-2d-quantization-dithering/" target="_blank" rel="noopener noreferrer">Dithering part three – real world 2D quantization dithering - Bart Wronski</a></p><p>試してみよう。</p><p>上記ブログの式は良く意味が分からないのでオリジナルのスライドを見ると、以下の式が書いてある。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">float3 magic = float3( 0.06711056, 0.00583715, 52.9829189 );</span>
<span class="line">return -scale + 2.0 * scale * frac( magic.z * frac( dot( sv_position, magic.xy ) ) );</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>ふむふむ。scaleは良くわからんがこんな感じか？</p><div class="language-mfg line-numbers-mode" data-highlighter="prismjs" data-ext="mfg"><pre><code class="language-mfg"><span class="line"><span class="token keyword">def</span> <span class="token tensor-name class-name">result_u8</span> <span class="token operator">|</span>x<span class="token punctuation">,</span> y<span class="token operator">|</span> <span class="token punctuation">{</span></span>
<span class="line">   <span class="token keyword">let</span> scale <span class="token operator">=</span> <span class="token number">1.0</span></span>
<span class="line">   <span class="token keyword">let</span> magic <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token number">0.06711056</span><span class="token punctuation">,</span> <span class="token number">0.00583715</span><span class="token punctuation">,</span> <span class="token number">52.9829189</span><span class="token punctuation">]</span></span>
<span class="line">   <span class="token keyword">let</span> fxy <span class="token operator">=</span> <span class="token builtin">f32</span><span class="token punctuation">(</span><span class="token punctuation">[</span>x<span class="token punctuation">,</span> y<span class="token punctuation">]</span><span class="token punctuation">)</span></span>
<span class="line">   <span class="token keyword">let</span> gray <span class="token operator">=</span> <span class="token operator">-</span>scale <span class="token operator">+</span> <span class="token number">2.0</span><span class="token operator">*</span>scale<span class="token operator">*</span>fract<span class="token punctuation">(</span>magic<span class="token punctuation">.</span>z<span class="token operator">*</span>fract<span class="token punctuation">(</span>dot<span class="token punctuation">(</span>fxy<span class="token punctuation">,</span> magic<span class="token punctuation">.</span>xy<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">  </span>
<span class="line">   <span class="token punctuation">[</span><span class="token operator">*</span><span class="token builtin">vec3</span><span class="token punctuation">(</span>gray<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">1.0</span><span class="token punctuation">]</span> <span class="token operator">|&gt;</span> lbgra_to_u8color<span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>結果は以下。</p><p><img src="/RandomThoughts/assets/2025_0828_114840-CDd2Jjgk.png" alt="imgs/Halftone/2025_0828_114840.png"></p><p>それっぽいノイズになったな。 サンプルしてみよう。</p><p><img src="/RandomThoughts/assets/2025_0828_115040-B166A_I9.png" alt="imgs/Halftone/2025_0828_115040.png"></p><p>悪くないな。写真でも試してみよう。</p><p><img src="/RandomThoughts/assets/2025_0828_115350-BivDRzwM.png" alt="imgs/Halftone/2025_0828_115350.png"></p><p>なんか写真は白いな。いまいち。</p><h2 id="循環パターンいろいろ" tabindex="-1"><a class="header-anchor" href="#循環パターンいろいろ"><span>循環パターンいろいろ</span></a></h2><p>ordered ditherは循環パターンと適当に補完すると面白い効果が出る、という事の一種に思う。 そこで循環パターンをいろいろ考える。</p><h3 id="sincosパターン" tabindex="-1"><a class="header-anchor" href="#sincosパターン"><span>sincosパターン</span></a></h3><p>shadertoyにあったコードはいろいろ複雑だが、結局整理すると単なるsinとcosの循環パターンと同じになる（オフセットが違うが）</p><div class="language-mfg line-numbers-mode" data-highlighter="prismjs" data-ext="mfg"><pre><code class="language-mfg"><span class="line"><span class="token keyword">let</span> PI <span class="token operator">=</span> <span class="token number">3.1415926</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">fn</span> <span class="token function">sincos_pat</span> <span class="token operator">|</span>sh<span class="token punctuation">:</span> <span class="token builtin">f32v2</span><span class="token punctuation">,</span> pscale<span class="token punctuation">:</span><span class="token builtin">f32</span> <span class="token operator">|</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">let</span> dir <span class="token operator">=</span> <span class="token punctuation">[</span>cos<span class="token punctuation">(</span>PI<span class="token operator">/</span><span class="token number">4.0</span><span class="token punctuation">)</span><span class="token punctuation">,</span> sin<span class="token punctuation">(</span>PI<span class="token operator">/</span><span class="token number">4.0</span><span class="token punctuation">)</span><span class="token punctuation">]</span></span>
<span class="line">  <span class="token keyword">let</span> ortho <span class="token operator">=</span> <span class="token punctuation">[</span>dir<span class="token punctuation">.</span>y<span class="token punctuation">,</span> <span class="token operator">-</span>dir<span class="token punctuation">.</span>x<span class="token punctuation">]</span></span>
<span class="line">  <span class="token number">0.5</span> <span class="token operator">+</span> <span class="token number">0.25</span> <span class="token operator">*</span> cos<span class="token punctuation">(</span>dot<span class="token punctuation">(</span>sh<span class="token punctuation">,</span> dir<span class="token punctuation">)</span> <span class="token operator">*</span> pscale<span class="token punctuation">)</span> <span class="token operator">+</span> <span class="token number">0.25</span> <span class="token operator">*</span> cos<span class="token punctuation">(</span>dot<span class="token punctuation">(</span>sh<span class="token punctuation">,</span> ortho<span class="token punctuation">)</span> <span class="token operator">*</span> pscale<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">def</span> <span class="token tensor-name class-name">result_u8</span> <span class="token operator">|</span>x<span class="token punctuation">,</span> y<span class="token operator">|</span> <span class="token punctuation">{</span></span>
<span class="line">   <span class="token keyword">let</span> dstCoord <span class="token operator">=</span> <span class="token builtin">f32</span><span class="token punctuation">(</span><span class="token punctuation">[</span>x<span class="token punctuation">,</span> y<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token operator">/</span><span class="token builtin">input_u8</span><span class="token punctuation">.</span>extent<span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span></span>
<span class="line">   <span class="token keyword">let</span> dotSize <span class="token operator">=</span> <span class="token number">6.0</span></span>
<span class="line">   <span class="token keyword">let</span> pscale <span class="token operator">=</span>  <span class="token number">2.0</span><span class="token operator">*</span>PI <span class="token operator">/</span> dotSize <span class="token operator">*</span> <span class="token number">680.0</span></span>
<span class="line"></span>
<span class="line">   <span class="token keyword">let</span> gray <span class="token operator">=</span> sincos_pat<span class="token punctuation">(</span>dstCoord<span class="token punctuation">,</span> pscale<span class="token punctuation">)</span></span>
<span class="line">   <span class="token punctuation">[</span><span class="token operator">*</span><span class="token builtin">vec3</span><span class="token punctuation">(</span>gray<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">1.0</span><span class="token punctuation">]</span> <span class="token operator">|&gt;</span> lbgra_to_u8color<span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>パターンとしては0.0から1.0で、sinとcosを斜めに進めるのを足し合わせる感じになっている。</p><p><img src="/RandomThoughts/assets/2025_0826_115232-BLFyEqjX.png" alt="imgs/Halftone/2025_0826_115232.png"></p><p>このパターンは、循環しているいい感じのパターンなら他でも良さそう。 という事で他のパターンも考えてみよう。</p><h3 id="円のパターン" tabindex="-1"><a class="header-anchor" href="#円のパターン"><span>円のパターン</span></a></h3><p>こういう感じの円はどうだろう？</p><p><img src="/RandomThoughts/assets/2025_0826_115410-_ZMWu1X2.png" alt="imgs/Halftone/2025_0826_115410.png"></p><p>中心のあたりが黒くて円周のあたりで白になるようなもの。円周のサイズは格子サイズの半分か1/4がいいかな。 適当に試して見てみよう。</p><div class="language-mfg line-numbers-mode" data-highlighter="prismjs" data-ext="mfg"><pre><code class="language-mfg"><span class="line"><span class="token keyword">fn</span> <span class="token function">circle_pat</span> <span class="token operator">|</span>sh<span class="token punctuation">:</span> <span class="token builtin">f32v2</span><span class="token punctuation">,</span> pscale<span class="token punctuation">:</span> <span class="token builtin">f32</span><span class="token operator">|</span> <span class="token punctuation">{</span></span>
<span class="line">   <span class="token keyword">let</span> gsize <span class="token operator">=</span> <span class="token number">6.0</span></span>
<span class="line">   <span class="token keyword">let</span> sxy <span class="token operator">=</span> sh<span class="token operator">*</span>pscale</span>
<span class="line">   <span class="token keyword">let</span> cxy <span class="token operator">=</span> round<span class="token punctuation">(</span>sxy<span class="token operator">/</span>gsize<span class="token punctuation">)</span><span class="token operator">*</span>gsize</span>
<span class="line">   <span class="token keyword">let</span> rxy <span class="token operator">=</span> sxy <span class="token operator">-</span> cxy</span>
<span class="line">   smoothstep<span class="token punctuation">(</span>gsize<span class="token operator">/</span><span class="token number">6.0</span><span class="token punctuation">,</span> gsize<span class="token operator">/</span><span class="token number">2.0</span><span class="token punctuation">,</span> length<span class="token punctuation">(</span>rxy<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><img src="/RandomThoughts/assets/2025_0826_123315-dcu0d0wK.png" alt="imgs/Halftone/2025_0826_123315.png"></p><p>まぁ書いた通りではある。smothstepは適当にそれっぽい放射状になるようにしている。</p><h3 id="円の外周パターン" tabindex="-1"><a class="header-anchor" href="#円の外周パターン"><span>円の外周パターン</span></a></h3><p>円の外周を4つ張り合わせたような、ひし形みたいなパターンも良くあるよな。 円の白と黒を逆にしてsmoothstepを逆にすればいいと思うんだが。</p><p>えーと、以下の式だよな。</p><div class="language-mfg line-numbers-mode" data-highlighter="prismjs" data-ext="mfg"><pre><code class="language-mfg"><span class="line">   smoothstep<span class="token punctuation">(</span>gsize<span class="token operator">/</span><span class="token number">6.0</span><span class="token punctuation">,</span> gsize<span class="token operator">/</span><span class="token number">2.0</span><span class="token punctuation">,</span> length<span class="token punctuation">(</span>rxy<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>lengthをgsize/2.0-lengthにして、smoothstepを適当に調整すればいいか。</p><p>いろいろ出力を見つつ調整して以下になる。</p><div class="language-mfg line-numbers-mode" data-highlighter="prismjs" data-ext="mfg"><pre><code class="language-mfg"><span class="line">   smoothstep<span class="token punctuation">(</span><span class="token number">0.0</span><span class="token punctuation">,</span> gsize<span class="token operator">/</span><span class="token number">8.0</span><span class="token punctuation">,</span> gsize<span class="token operator">/</span><span class="token number">2.0</span><span class="token operator">-</span><span class="token number">0.8</span><span class="token operator">*</span>length<span class="token punctuation">(</span>rxy<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>関数全体ではこんな感じ。</p><div class="language-mfg line-numbers-mode" data-highlighter="prismjs" data-ext="mfg"><pre><code class="language-mfg"><span class="line"><span class="token keyword">fn</span> <span class="token function">inv_circle_pat</span> <span class="token operator">|</span>sh<span class="token punctuation">:</span> <span class="token builtin">f32v2</span><span class="token punctuation">,</span> pscale<span class="token punctuation">:</span> <span class="token builtin">f32</span><span class="token operator">|</span> <span class="token punctuation">{</span></span>
<span class="line">   <span class="token keyword">let</span> gsize <span class="token operator">=</span> <span class="token number">6.0</span></span>
<span class="line">   <span class="token keyword">let</span> sxy <span class="token operator">=</span> sh<span class="token operator">*</span>pscale</span>
<span class="line">   <span class="token keyword">let</span> cxy <span class="token operator">=</span> round<span class="token punctuation">(</span>sxy<span class="token operator">/</span>gsize<span class="token punctuation">)</span><span class="token operator">*</span>gsize</span>
<span class="line">   <span class="token keyword">let</span> rxy <span class="token operator">=</span> sxy <span class="token operator">-</span> cxy</span>
<span class="line">   smoothstep<span class="token punctuation">(</span><span class="token number">0.0</span><span class="token punctuation">,</span> gsize<span class="token operator">/</span><span class="token number">8.0</span><span class="token punctuation">,</span> gsize<span class="token operator">/</span><span class="token number">2.0</span><span class="token operator">-</span><span class="token number">0.8</span><span class="token operator">*</span>length<span class="token punctuation">(</span>rxy<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><img src="/RandomThoughts/assets/2025_0826_132629-HcOGkU_p.png" alt="imgs/Halftone/2025_0826_132629.png"></p><p>イメージしていたものにはなった。</p>`,99)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};